corpus_block("test-stat-summary.R: stat_summary(_bin) work with lambda expressions", {
  dat <- data_frame(
      x = c(1, 1, 2, 2, 3, 3),
      y = c(0, 2, 1, 3, 2, 4)
    )
  .plot("test-stat-summary.R: stat_summary(_bin) work with lambda expressions #1", p1 <- ggplot(dat, aes(x, y)) +
      stat_summary(fun.data = mean_se))
  .plot("test-stat-summary.R: stat_summary(_bin) work with lambda expressions #2", p2 <- ggplot(dat, aes(x, y)) +
      stat_summary(fun.data = ~ {
        mean <- mean(.x)
        se <- sqrt(stats::var(.x) / length(.x))
        data_frame(y = mean, ymin = mean - se, ymax = mean + se)
      }))
  .plot("test-stat-summary.R: stat_summary(_bin) work with lambda expressions #3", p3 <- ggplot(dat, aes(x, y)) +
      stat_summary(
        fun = ~ mean(.x),
        fun.min = ~ mean(.x) - sqrt(stats::var(.x) / length(.x)),
        fun.max = ~ mean(.x) + sqrt(stats::var(.x) / length(.x))
      ))
})

